    clipper.Execute(Clipper2Lib::ClipType::Intersection, Clipper2Lib::FillRule::EvenOdd, solution);

    // 3. Convert PolyTree64 back to PolygonWithHoles2d
    std::vector<PolygonWithHoles2d> result;

    // Helper to traverse the PolyTree and group outer boundaries with their children (holes)
    std::function<void(const Clipper2Lib::PolyPath64*)> traverse = [&](const Clipper2Lib::PolyPath64* node) {
        for (auto child : node->Childs()) {
            if (!child->IsHole()) {
                PolygonWithHoles2d poly;
                // Convert outer boundary
                std::vector<Point2d> outer;
                for (const auto& pt : child->Polygon()) {
                    outer.push_back({(double)pt.x, (double)pt.y});
                }
                poly.outer_boundary = outer;

                // Process immediate children of this outer boundary as holes
                for (auto holeNode : child->Childs()) {
                    std::vector<Point2d> hole;
                    for (const auto& pt : holeNode->Polygon()) {
                        hole.push_back({(double)pt.x, (double)pt.y});
                    }
                    poly.holes.push_back(hole);

                    // If the hole has children, they are nested polygons (islands)
                    if (!holeNode->Childs().empty()) {
                        traverse(holeNode);
                    }
                }
                result.push_back(poly);
            }
        }
    };

    traverse(&solution);
    return result;

